/**
 * An explicit escape hatch for a platform id that could not be represented by
 * a portable catalog reference. The object wrapper makes raw ids impossible to
 * pass accidentally where the public API normally expects a typed ref.
 */
export interface UnsafePlatformId {
    readonly __unsafe: "platformId";
    readonly value: string;
}
/** Mark a non-portable platform id intentionally. Prefer catalog refs whenever possible. */
export declare function unsafePlatformId(value: string): UnsafePlatformId;
/** Check whether `value` is an `UnsafePlatformId` wrapper. */
export declare function isUnsafePlatformId(value: unknown): value is UnsafePlatformId;
